public class Book
{
    public int Id { get; set; }
    public string Title { get; set; }
    public string Author { get; set; }
    public decimal Price { get; set; }
}

public class Query
{
    private static readonly List<Book> _books = new()
    {
        new Book { Id = 1, Title = "GraphQL in Action", Author = "Samer Buna", Price = 39.99m },
        new Book { Id = 2, Title = "Learning GraphQL", Author = "Eve Porcello", Price = 29.99m }
    };

    [Query]
    public IEnumerable<Book> GetBooks() => _books;

    [Query]
    public Book? GetBookById(int id) => _books.FirstOrDefault(b => b.Id == id);
}

public class Mutation
{
    [Mutation]
    public Book AddBook(string title, string author, decimal price)
    {
        var book = new Book
        {
            Id = _books.Max(b => b.Id) + 1,
            Title = title,
            Author = author,
            Price = price
        };

        _books.Add(book);
        return book;
    }
}

